head.script:
scwin.trigger1_onclick = function(e) { //debugger;
    wc.createWindow("title" + title, null, "windowContainer_controlIconPosition_WEFF-109_(WSQ-3185)_sub.xml", 'test', i, '', '');
    windowContainer1.createWindow("title" + title, null, "windowContainer_controlIconPosition_WEFF-109_(WSQ-3185)_sub.xml", 'test', i, '', '');
    /*wc.createWindow( "title" + title ,
     null ,
     "windowContainer_controlIconPosition_WEFF-109_(WSQ-3185)_sub.xml",
     'test',
     i,
     '',
     '',
     '',
     true,
     "all");*/
    winc = Number(winc) + 1;
    title = Number(title) + 1;
    i++;
};
scwin.trigger2_onclick = function(e) {
    multi.changeAction("test2.do?param=1");
};
scwin.onwindowchange = function(e) {
    log = arguments[1];
    //console.log("onwindowchange##### oldWindowId = " + arguments[0] + ", newWindowId = " + arguments[1]);
};
scwin.onclosewindow = function(e) {
    console.log("onclosewindow##### e.src = " + e.src + ", e,title = " + e.title);
};
scwin.onwindowtabclick = function(e) {
    console.log("onwindowtabclick##### oldWindowId = " + arguments[0] + ", newWindowId = " + arguments[1]);
}
scwin.checkVal1 = function() {
    return window.getComputedStyle(WebSquare.wUnit.getDomById($p.id + 'wc_controlIcon')).getPropertyValue('right') == '0px';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. windowContainer하단에 있는 button을 3번 click한다.
    //2. Click the button three times under the windowContainer.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 상단에 3개의 window창이 생성되어 보여진다.
    //2. Three window windows are created and displayed at the top.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wc_name').offsetTop == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. windowContainer 상단의 메뉴에서 멀티창을 클릭한다.
    //3. In the menu at the top of the windowContainer, click Multi-pane.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc_sequential').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 멀티창으로 변경되어 보여진다.
    //3. It will be changed to multi window.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_subWindow0').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_subWindow1').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_subWindow2').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_subWindow0').style.top == '138px'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_subWindow1').style.top == '0px'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_subWindow2').style.top == '0px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 각각의 window창을 클릭하여 상단의 네임 레이어에 포커스가 이동되지는 확인한다.
    // 4. Click on each window to make sure that the focus is moved to the top layer.
    //Verify 4. 네임 레이어에 포커스가 이동되어 보여진다.
    //4. The focus is moved to the name layer.
    //Title3
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc_subWindow2_header_title').click()");
    WebSquare.wUnit.addCommand("assert", "log == 3", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Title2
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc_subWindow1_header_title').click()");
    WebSquare.wUnit.addCommand("assert", "log == 2", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Title1
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc_subWindow0_header_title').click()");
    WebSquare.wUnit.addCommand("assert", "log == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.winc = "1";
    window.title = "1";
    window.i = 1;
    tsClose = function(e) {
        //	debugger;
        //	alert('gkgk');
    };
    window.log;
}
